package io.github.diodeme.ji.host;

import java.security.KeyPair;
import java.util.List;
import java.util.Optional;

/** Durable Host identity and paired-device boundary, independent from Provider master keys. */
public interface HostDeviceStore extends AutoCloseable {
    KeyPair identity();
    Optional<Device> device(String deviceId);
    List<Device> devices();
    void save(Device device);
    void remove(String deviceId);

    @Override
    default void close() {}

    record Device(String deviceId, byte[] publicKey, String role) {
        public Device {
            if (deviceId == null || deviceId.isBlank() || publicKey == null || publicKey.length < 32
                    || role == null || role.isBlank()) {
                throw new IllegalArgumentException("invalid paired device");
            }
            publicKey = publicKey.clone();
        }

        @Override public byte[] publicKey() { return publicKey.clone(); }
        @Override public String toString() { return "Device[deviceId=" + deviceId + ",role=" + role + "]"; }
    }
}
